<?php
require_once "../config/database.php";
$id=(int)($_GET["id"]??0); $s=$conn->prepare("SELECT pr.*, pi.id AS item_id, pi.medicine_id, pi.dosage, pi.frequency, pi.duration, pi.quantity FROM prescriptions pr LEFT JOIN prescription_items pi ON pi.prescription_id=pr.id WHERE pr.id=? LIMIT 1"); $s->bind_param("i",$id); $s->execute(); $prescription=$s->get_result()->fetch_assoc(); if(!$prescription) die("Prescription not found.");
$error=""; $patients=$conn->query("SELECT id,patient_number,first_name,last_name FROM patients ORDER BY last_name,first_name"); $doctors=$conn->query("SELECT id,first_name,last_name FROM doctors ORDER BY last_name,first_name"); $medicines=$conn->query("SELECT id,medicine_name,quantity FROM medicines ORDER BY medicine_name");
if($_SERVER["REQUEST_METHOD"]==="POST"){ $patient_id=(int)$_POST["patient_id"]; $doctor_id=(int)$_POST["doctor_id"]; $medicine_id=(int)$_POST["medicine_id"]; $quantity=(int)$_POST["quantity"]; $date=$_POST["prescription_date"]; $dosage=trim($_POST["dosage"]??""); $frequency=trim($_POST["frequency"]??""); $duration=trim($_POST["duration"]??""); $s=$conn->prepare("UPDATE prescriptions SET patient_id=?,doctor_id=?,prescription_date=? WHERE id=?"); $s->bind_param("iisi",$patient_id,$doctor_id,$date,$id); $item=$conn->prepare("UPDATE prescription_items SET medicine_id=?,dosage=?,frequency=?,duration=?,quantity=? WHERE id=?"); $item->bind_param("isssii",$medicine_id,$dosage,$frequency,$duration,$quantity,$prescription["item_id"]); if($s->execute() && $item->execute()){header("Location:index.php");exit;} $error=$conn->error ?: "Unable to update prescription."; $prescription=array_merge($prescription,$_POST); }
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Edit Prescription</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><div class="container"><h1>Edit Prescription</h1><?php if($error): ?><p class="error"><?=htmlspecialchars($error)?></p><?php endif; ?><form method="post">
<label>Patient</label><select name="patient_id" required><?php while($p=$patients->fetch_assoc()): ?><option value="<?=$p["id"]?>" <?=$prescription["patient_id"]==$p["id"]?"selected":""?>><?=htmlspecialchars($p["patient_number"]." - ".$p["first_name"]." ".$p["last_name"])?></option><?php endwhile; ?></select>
<label>Doctor</label><select name="doctor_id" required><?php while($d=$doctors->fetch_assoc()): ?><option value="<?=$d["id"]?>" <?=$prescription["doctor_id"]==$d["id"]?"selected":""?>><?=htmlspecialchars($d["first_name"]." ".$d["last_name"])?></option><?php endwhile; ?></select>
<label>Medicine</label><select name="medicine_id" required><?php while($m=$medicines->fetch_assoc()): ?><option value="<?=$m["id"]?>" <?=$prescription["medicine_id"]==$m["id"]?"selected":""?>><?=htmlspecialchars($m["medicine_name"])?></option><?php endwhile; ?></select>
<label>Quantity</label><input type="number" name="quantity" min="1" value="<?=htmlspecialchars($prescription["quantity"])?>" required><label>Dosage</label><input name="dosage" value="<?=htmlspecialchars($prescription["dosage"]??"")?>"><label>Frequency</label><input name="frequency" value="<?=htmlspecialchars($prescription["frequency"]??"")?>"><label>Duration</label><input name="duration" value="<?=htmlspecialchars($prescription["duration"]??"")?>"><label>Date</label><input type="date" name="prescription_date" value="<?=htmlspecialchars($prescription["prescription_date"])?>" required><button type="submit">Save Changes</button></form><a href="index.php">← Back</a></div></body></html>
